const n=document.getElementById("nav-toggle"),s=document.getElementById("mobile-menu"),t=document.getElementById("nav-icon");n?.addEventListener("click",()=>{const e=!s?.classList.contains("hidden");s?.classList.toggle("hidden",e),t?.classList.toggle("fa-bars",e),t?.classList.toggle("fa-times",!e)});document.querySelectorAll(".mobile-nav-link").forEach(e=>{e.addEventListener("click",()=>{s?.classList.add("hidden"),t?.classList.add("fa-bars"),t?.classList.remove("fa-times")})});
